from flask import Blueprint, request
from store import store
from models import make_versioned, touch, serialize
from middleware import check_role_permission
from response import success_response
from errors import (
    raise_error, ERR_FORBIDDEN, ERR_NOT_FOUND, ERR_INVALID_STATE,
    ERR_VALIDATION, ERR_SUSPEND_CRITERIA_NOT_MET,
)

bp = Blueprint("riders", __name__)


@bp.route("/api/riders", methods=["POST"])
def create_rider():
    check_role_permission({"PlatformAdmin"})
    data = request.get_json(force=True, silent=True) or {}

    name = data.get("name")
    if not name or not isinstance(name, str) or len(name.strip()) == 0:
        raise_error(ERR_VALIDATION, "name is required")

    phone = data.get("phone")
    if not phone or not isinstance(phone, str):
        raise_error(ERR_VALIDATION, "phone is required")

    for r in store.riders.values():
        if r["phone"] == phone:
            raise_error(ERR_VALIDATION, "phone must be unique across all riders")

    rider = make_versioned({
        "name": name,
        "phone": phone,
        "status": "OFFLINE",
        "wallet_balance_cents": 0,
        "on_time_rate": 1.0,
        "acceptance_rate": 1.0,
        "rating": 5.0,
        "bonus_tier": "BRONZE",
    })
    store.riders[rider["id"]] = rider
    return success_response(serialize(rider), 201)


@bp.route("/api/riders/<rider_id>", methods=["GET"])
def get_rider(rider_id):
    check_role_permission({"PlatformAdmin", "Rider", "CustomerService"})
    rider = store.riders.get(rider_id)
    if not rider:
        raise_error(ERR_NOT_FOUND, "Rider not found")

    if request.user_role == "Rider" and request.user_id != rider_id:
        raise_error(ERR_FORBIDDEN, "Cannot read another rider's profile")

    return success_response(serialize(rider))


@bp.route("/api/riders/<rider_id>/go-online", methods=["POST"])
def go_online(rider_id):
    check_role_permission({"Rider"})
    rider = store.riders.get(rider_id)
    if not rider:
        raise_error(ERR_NOT_FOUND, "Rider not found")
    if request.user_id != rider_id:
        raise_error(ERR_FORBIDDEN, "Cannot go online for another rider")
    if rider["status"] != "OFFLINE":
        raise_error(ERR_INVALID_STATE, "Rider must be OFFLINE to go online")
    rider["status"] = "AVAILABLE"
    touch(rider)
    return success_response(serialize(rider))


@bp.route("/api/riders/<rider_id>/go-offline", methods=["POST"])
def go_offline(rider_id):
    check_role_permission({"Rider"})
    rider = store.riders.get(rider_id)
    if not rider:
        raise_error(ERR_NOT_FOUND, "Rider not found")
    if request.user_id != rider_id:
        raise_error(ERR_FORBIDDEN, "Cannot go offline for another rider")
    if rider["status"] != "AVAILABLE":
        raise_error(ERR_INVALID_STATE, "Rider must be AVAILABLE to go offline")

    has_active = any(
        a["rider_id"] == rider_id and a["status"] in ("OFFERED", "ACCEPTED", "PICKED_UP")
        for a in store.assignments.values()
    )
    if has_active:
        raise_error(ERR_INVALID_STATE, "Cannot go offline with active assignments")

    rider["status"] = "OFFLINE"
    touch(rider)
    return success_response(serialize(rider))


@bp.route("/api/riders/<rider_id>/suspend", methods=["POST"])
def suspend_rider(rider_id):
    check_role_permission({"PlatformAdmin"})
    rider = store.riders.get(rider_id)
    if not rider:
        raise_error(ERR_NOT_FOUND, "Rider not found")
    if rider["status"] != "AVAILABLE":
        raise_error(ERR_INVALID_STATE, "Rider must be AVAILABLE to suspend")
    if rider["on_time_rate"] >= 0.70 and rider["acceptance_rate"] >= 0.50:
        raise_error(ERR_SUSPEND_CRITERIA_NOT_MET, "Performance thresholds not breached")
    rider["status"] = "SUSPENDED"
    touch(rider)
    return success_response(serialize(rider))

from store import store
from services.computations import recompute_bonus_tier


def recompute_acceptance_rate(rider):
    rider_id = rider["id"]
    relevant = []
    for a in store.assignments.values():
        if a["rider_id"] == rider_id and a["status"] in ("ACCEPTED", "PICKED_UP", "DELIVERED", "REJECTED"):
            relevant.append(a)
    relevant.sort(key=lambda a: a["created_at"], reverse=True)
    last_30 = relevant[:30]
    if len(last_30) == 0:
        rider["acceptance_rate"] = 1.0
        return
    accepted_count = sum(1 for a in last_30 if a["status"] in ("ACCEPTED", "PICKED_UP", "DELIVERED"))
    rider["acceptance_rate"] = round(accepted_count / len(last_30), 10)


def recompute_on_time_rate(rider):
    rider_id = rider["id"]
    delivered = []
    for a in store.assignments.values():
        if a["rider_id"] == rider_id and a["status"] == "DELIVERED":
            delivered.append(a)
    delivered.sort(key=lambda a: a["created_at"], reverse=True)
    last_30 = delivered[:30]
    if len(last_30) < 10:
        rider["on_time_rate"] = 1.0
        return
    on_time_count = 0
    for a in last_30:
        order = store.orders.get(a["order_id"])
        if order and (order.get("minutes_late") or 0) == 0:
            on_time_count += 1
    rider["on_time_rate"] = round(on_time_count / len(last_30), 10)

from flask import Blueprint, request
from store import store
from models import make_versioned, touch, serialize
from middleware import check_role_permission
from response import success_response
from pagination import get_pagination_params, paginate
from clock import now, format_timestamp
from datetime import timedelta
from errors import (
    raise_error, ERR_FORBIDDEN, ERR_NOT_FOUND, ERR_INVALID_STATE,
    ERR_VALIDATION, ERR_ORDER_INVALID, ERR_RESTAURANT_UNAVAILABLE,
)
from services.computations import (
    haversine_km, is_peak_time, compute_delivery_fee,
    compute_tiered_commission,
)

bp = Blueprint("orders", __name__)


@bp.route("/api/orders", methods=["POST"])
def place_order():
    check_role_permission({"Customer"})
    data = request.get_json(force=True, silent=True) or {}

    customer_id = data.get("customer_id")
    if not customer_id:
        raise_error(ERR_VALIDATION, "customer_id is required")
    customer = store.customers.get(customer_id)
    if not customer:
        raise_error(ERR_NOT_FOUND, "Customer not found")

    restaurant_id = data.get("restaurant_id")
    if not restaurant_id:
        raise_error(ERR_VALIDATION, "restaurant_id is required")
    restaurant = store.restaurants.get(restaurant_id)
    if not restaurant:
        raise_error(ERR_NOT_FOUND, "Restaurant not found")

    if request.user_id != customer_id:
        raise_error(ERR_FORBIDDEN, "Cannot place order for another customer")

    if restaurant["status"] != "ACTIVE":
        raise_error(ERR_RESTAURANT_UNAVAILABLE, "Restaurant is not active")

    items = data.get("items")
    if not items or not isinstance(items, list) or len(items) == 0:
        raise_error(ERR_ORDER_INVALID, "items must be a non-empty array")

    order_items = []
    for entry in items:
        menu_item_id = entry.get("menu_item_id")
        if not menu_item_id:
            raise_error(ERR_VALIDATION, "menu_item_id is required in each item")
        mi = store.menu_items.get(menu_item_id)
        if not mi:
            raise_error(ERR_NOT_FOUND, f"Menu item {menu_item_id} not found")
        if mi["restaurant_id"] != restaurant_id:
            raise_error(ERR_RESTAURANT_UNAVAILABLE, "Menu item does not belong to this restaurant")
        if not mi["is_listed"]:
            raise_error(ERR_RESTAURANT_UNAVAILABLE, "Menu item is not listed")

        quantity = entry.get("quantity", 1)
        if not isinstance(quantity, int) or quantity < 1:
            raise_error(ERR_ORDER_INVALID, "quantity must be >= 1")

        order_items.append({
            "menu_item_id": menu_item_id,
            "name": mi["name"],
            "unit_price_cents": mi["price_cents"],
            "quantity": quantity,
        })

    subtotal_cents = sum(i["unit_price_cents"] * i["quantity"] for i in order_items)
    if subtotal_cents < 100:
        raise_error(ERR_ORDER_INVALID, "Minimum order size is 100 cents")

    placement_time = now()
    distance_km = haversine_km(restaurant["lat"], restaurant["lng"], customer["lat"], customer["lng"])
    peak = is_peak_time(placement_time)
    provisional_fee = compute_delivery_fee(distance_km, peak)
    provisional_commission = compute_tiered_commission(subtotal_cents)
    promised_delivery_time = format_timestamp(placement_time + timedelta(minutes=45))

    order = make_versioned({
        "customer_id": customer_id,
        "restaurant_id": restaurant_id,
        "rider_id": None,
        "items": order_items,
        "subtotal_cents": subtotal_cents,
        "distance_km": distance_km,
        "is_peak": peak,
        "promised_delivery_time": promised_delivery_time,
        "provisional_delivery_fee_cents": provisional_fee,
        "final_delivery_fee_cents": None,
        "provisional_commission_cents": provisional_commission,
        "final_commission_cents": None,
        "actual_delivery_time": None,
        "minutes_late": None,
        "status": "PLACED",
        "payment_status": "AUTHORIZED",
    })
    order["_promised_dt"] = placement_time + timedelta(minutes=45)
    store.orders[order["id"]] = order
    return success_response(serialize(order), 201)


